To prevent duplicate stakeholder classes from being stored, it is recommended to deduplicate the trimmed values using a `Set` during sanitization. This ensures data integrity and avoids potential duplicate rendering or evaluation issues.

```typescript
function sanitizeRepresentedStakeholderClasses(
  value: unknown
): readonly string[] | null {
  if (!Array.isArray(value)) {
    return null
  }

  const next = new Set<string>()
  for (const entry of value) {
    if (typeof entry !== 'string') {
      return null
    }
    const trimmed = entry.trim()
    if (trimmed.length > 0) {
      next.add(trimmed)
    }
  }

  if (next.size === 0) {
    return null
  }

  return Object.freeze(Array.from(next))
}
