Similarly, deduplicating the authorized decision scopes using a `Set` prevents duplicate scopes from being registered, ensuring cleaner downstream evaluation and UI rendering.

```typescript
function sanitizeAuthorizedDecisionScopes(
  value: unknown
): readonly CommunityAdvisoryDecisionScope[] | null {
  if (!Array.isArray(value) || value.length === 0) {
    return null
  }

  const next = new Set<CommunityAdvisoryDecisionScope>()
  for (const entry of value) {
    if (!isCommunityAdvisoryDecisionScope(entry)) {
      return null
    }
    next.add(entry)
  }

  return Object.freeze(Array.from(next))
}
